INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured", "sponsored", "sponsor_name", "en_title", "en_dek", "en_body_html", "en_published")
SELECT 'U17 : la Brio Youth Academy s''offre la MIFA, l''académie internationale du FC Metz (3-2)', 'u17-la-brio-youth-academy-s-offre-la-mifa-academie-internationale-du-fc-metz', 'En match amical, les U17 de la Brio Youth Academy ont battu la MIFA, l''académie internationale du FC Metz, au terme d''une rencontre disputée (3-2). Premier épisode de notre nouvelle rubrique consacrée à notre partenaire n°1.', '<p>Passe D ouvre une nouvelle rubrique avec son partenaire n°1, la <strong>Brio Youth Academy</strong>. Ici, on vous racontera les matchs de l''académie et on prendra des nouvelles des joueurs passés par la maison, partis tenter leur chance dans leurs nouveaux clubs. Et pour ce premier épisode, les U17 ont frappé fort.</p><h2>Un adversaire de référence</h2><p>En face, il y avait la <strong>MIFA</strong>, la Metz International Football Academy. Créée en 2013 au sein de l''écosystème du <strong>FC Metz</strong>, elle forme des joueurs du monde entier, de 13 à 18 ans, avec un double projet sportif et scolaire, en s''appuyant sur l''expertise du centre de formation messin. Un centre qui a vu passer Robert Pires, Miralem Pjanić, Kalidou Koulibaly ou Sadio Mané. Autant dire que le test était sérieux.</p><h2>Un match disputé jusqu''au bout</h2><p>Les deux équipes se sont rendu coup pour coup dans une rencontre intense et très engagée. Les U17 de la Brio Youth Academy ont dû s''employer face à des adversaires bien organisés et techniques, mais ils ont su faire la différence pour s''imposer <strong>3-2</strong>.</p><p>Au-delà du score, c''est l''état d''esprit qu''on retiendra : de l''exigence, de la solidarité et la capacité à répondre présent face à une structure liée à un club professionnel. Exactement ce que l''académie veut développer chez ses joueurs.</p><h2>La composition de départ</h2><p>Pour ce match, le staff avait aligné un <strong>4-2-1-3</strong>, avec <strong>Cheikh</strong> comme capitaine :</p><ul><li><strong>Gardien</strong> : Kagan (1)</li><li><strong>Défense</strong> : Mattea (2), Issa (5), Sanjin (4), Eliezer (3)</li><li><strong>Milieu</strong> : Cheikh (6, capitaine), Mehdi (8) ; Aleksa (10) en meneur de jeu</li><li><strong>Attaque</strong> : Sékou K. (7), Luca (9), IBK (11)</li><li><strong>Remplaçants</strong> : Evan (12), Kenzi (13), Adem (14), Samael (15)</li></ul><h2>La Brio Youth Academy, c''est quoi ?</h2><p>Basée à Paris, la Brio Youth Academy accompagne des joueurs des U10 aux seniors. Au programme : des entraînements exigeants, des matchs contre des clubs professionnels et semi-professionnels, et des tournois internationaux. L''académie mise aussi sur une formation globale, avec soutien scolaire et moments de cohésion, parce qu''un joueur bien entouré progresse plus vite.</p><p>Selon l''académie, des clubs en France, en Italie, en Espagne et en Andorre lui font déjà confiance pour leur recrutement.</p><h2>Rendez-vous dans cette rubrique</h2><p>Résultats des matchs, parcours des anciens dans leurs nouveaux clubs, coulisses de l''académie : vous retrouverez tout ici, dans la rubrique Brio Youth Academy. Bravo aux U17 pour cette belle victoire ! 💪</p><p>— Passe D</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'brio-youth-academy'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 3, false, true, 'Brio Youth Academy', 'U17: Brio Youth Academy beat MIFA, FC Metz''s international academy (3-2)', 'In a friendly, Brio Youth Academy''s U17s beat MIFA, FC Metz''s international academy, in a hard-fought game (3-2). The first episode of our new section dedicated to our number one partner.', '<p>Passe D is launching a new section with its number one partner, <strong>Brio Youth Academy</strong>. Here, we will cover the academy''s games and follow the players who came through it and are now trying their luck at new clubs. And for this first episode, the U17s made a statement.</p><h2>A serious opponent</h2><p>On the other side was <strong>MIFA</strong>, the Metz International Football Academy. Founded in 2013 as part of the <strong>FC Metz</strong> set-up, it trains players from all over the world, aged 13 to 18, combining football and school, and draws on the expertise of the Metz academy. That academy produced Robert Pires, Miralem Pjanić, Kalidou Koulibaly and Sadio Mané. In other words, this was a real test.</p><h2>A tight game to the end</h2><p>The two teams traded blows in an intense, hard-fought game. Brio Youth Academy''s U17s had to dig deep against well-organised, technical opponents, but they found the difference to win <strong>3-2</strong>.</p><p>Beyond the score, the attitude is what stands out: high standards, team spirit and the ability to step up against a structure linked to a professional club. Exactly what the academy wants to build in its players.</p><h2>The starting line-up</h2><p>For this game, the staff went with a <strong>4-2-1-3</strong>, with <strong>Cheikh</strong> as captain:</p><ul><li><strong>Goalkeeper</strong>: Kagan (1)</li><li><strong>Defence</strong>: Mattea (2), Issa (5), Sanjin (4), Eliezer (3)</li><li><strong>Midfield</strong>: Cheikh (6, captain), Mehdi (8); Aleksa (10) as playmaker</li><li><strong>Attack</strong>: Sékou K. (7), Luca (9), IBK (11)</li><li><strong>Substitutes</strong>: Evan (12), Kenzi (13), Adem (14), Samael (15)</li></ul><h2>What is Brio Youth Academy?</h2><p>Based in Paris, Brio Youth Academy works with players from U10 to seniors. On the programme: demanding training sessions, games against professional and semi-professional clubs, and international tournaments. The academy also believes in all-round development, with school support and team-building moments, because a well-supported player improves faster.</p><p>According to the academy, clubs in France, Italy, Spain and Andorra already trust it for their recruitment.</p><h2>See you in this section</h2><p>Match results, former players'' journeys at their new clubs, behind the scenes at the academy: you will find it all here, in the Brio Youth Academy section. Well done to the U17s on a great win! 💪</p><p>— Passe D</p>', true
ON CONFLICT ("slug") DO NOTHING;
